import ledger


def _encode(cents):
    n = int(cents)
    sign = '-' if n < 0 else '+'
    digits = str(abs(n))
    check = sum(int(d) for d in digits) % 10
    return "{}{}#{}".format(sign, digits, check)


def transfer(acct, cents, reason):
    return ledger.post(acct, _encode(cents), memo=reason)
